wwv_flow_api.create_report_region(
 p_id=>wwv_flow_api.id(3558871336814012)
,p_name=>'Horário'
,p_template=>wwv_flow_api.id(1802396702580422)
,p_display_sequence=>10
,p_include_in_reg_disp_sel_yn=>'N'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_display_point=>'BODY'
,p_source=>wwv_flow_utilities.join(wwv_flow_t_varchar2(
'select A.PERI_IN_ID, per.PERI_ST_NOME, tur.tur_in_id,  ''\''||A.hose_st_horario||''\'' as hose_st_horario, ',
'       A.hose_st_horario as hose_st_horario_display,',
'nvl(MAX(A.seg),''[Incluir]'') as DISC_02, nvl(MAX(A.ter),''[Incluir]'') as DISC_03, nvl(MAX(A.qua),''[Incluir]'') as DISC_04, nvl(MAX(A.qui),''[Incluir]'') as DISC_05, nvl(MAX(A.sex),''[Incluir]'') as DISC_06, nvl(MAX(A.sab),''[Incluir]'') as DISC_07',
'  from (select hose.peri_in_id, ',
'               aula.turn_in_id, ',
'               dis.disc_st_nome, ',
'               nvl(hose.hose_st_horario,aula.aula_ch_hora_ini) as hose_st_horario, ',
'               hose.hose_in_diasem,      ',
'               hose.disc_in_id',
'          from tbl_horario_semana hose',
'          LEFT JOIN tbl_turno_aula aula ON aula.aula_ch_hora_ini = hose.hose_st_horario',
'          LEFT JOIN tbl_disciplina dis  ON dis.disc_in_id = hose.disc_in_id)',
'pivot (MAX(DISC_ST_NOME) for hose_in_diasem in ( 2 as seg, 3 as ter, 4 as qua, 5 as qui, 6 as sex, 7 as sab)) A',
' LEFT JOIN tbl_periodo per ON per.peri_in_id = A.peri_in_id',
' LEFT JOIN tbl_turma tur   ON tur.turn_in_id = A.turn_in_id',
'WHERE (A.PERI_IN_ID = :P30_PERIODO OR :P30_PERIODO IS NULL)',
'  AND (tur.tur_in_id = :P30_TURMA  OR :P30_TURMA IS NULL)',
'group by A.PERI_IN_ID, per.PERI_ST_NOME, tur.tur_in_id, A.hose_st_horario',
'union',
'select B.peri_in_id, B.peri_St_nome, B.tur_in_id, ''\''||aula_ch_hora_ini||''\'' as hose_st_horario, B.aula_ch_hora_ini as hose_st_horario_display, ',
'       ''[Incluir]'' as DISC_02, ''[Incluir]'' as DISC_03, ''[Incluir]'' as DISC_04, ''[Incluir]'' as DISC_05, ''[Incluir]'' as DISC_06, ''[Incluir]'' as DISC_07 ',
'  from (select p2.peri_in_id, p2.peri_st_nome, tur1.tur_in_id, aula1.aula_ch_hora_ini',
'          from tbl_periodo p2',
'             , tbl_turno_aula aula1',
'             , tbl_turma      tur1',
'         where tur1.turn_in_id = aula1.turn_in_id) B',
'WHERE (B.PERI_IN_ID = :P30_PERIODO OR :P30_PERIODO IS NULL)',
'  AND (B.tur_in_id = :P30_TURMA  OR :P30_TURMA IS NULL)',
'  AND NOT EXISTS (select 1 ',
'                    from tbl_horario_semana hose2',
'                    LEFT JOIN tbl_turno_aula aula2 ON aula2.aula_ch_hora_ini = hose2.hose_st_horario',
'                    LEFT JOIN tbl_disciplina dis2  ON dis2.disc_in_id = hose2.disc_in_id',
'                   WHERE nvl(hose2.hose_st_horario,aula2.aula_ch_hora_ini) = B.aula_ch_hora_ini',
'                     AND hose2.peri_in_id = B.PERI_IN_ID',
'                     AND hose2.tur_in_id  = B.TUR_IN_ID',
'                     and hose2.hose_st_horario = B.aula_ch_hora_ini)',
'ORDER BY 2, 3 ,5'))
,p_source_type=>'NATIVE_SQL_REPORT'
,p_ajax_enabled=>'Y'
,p_query_row_template=>wwv_flow_api.id(1803571714580436)
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_break_cols=>'0'
,p_query_no_data_found=>'No data found.'
,p_query_num_rows_type=>'ROW_RANGES_IN_SELECT_LIST'
,p_query_row_count_max=>500
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_break_type_flag=>'DEFAULT_BREAK_FORMATTING'
,p_csv_output=>'Y'
,p_csv_output_link_text=>'Download'
,p_prn_output=>'Y'
,p_prn_format=>'PDF'
,p_prn_output_link_text=>'PDF'
,p_plug_query_strip_html=>'Y'
);
