,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'Y'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_utilities.join(wwv_flow_t_varchar2(
'DECLARE',
'  CURSOR C_CURR IS',
'    SELECT C1.CURR_ST_CODIGO, ',
'           C1.CURR_ST_DETALHES, ',
'           C1.CURR_IN_CH_TOTAL,            FC_REFERENCIA_DESCRICAO(''PERIODICIDADE'',C2.CUR_IN_PERIODICIDADE) P43_PERIODICIDADE',
'      FROM TBL_CURRICULO C1',
'         , TBL_CURSO C2',
'     WHERE C2.CUR_IN_ID = C1.CUR_IN_ID',
'       AND C1.CURR_IN_ID = :P43_CURR_IN_ID;',
'W_CURR_ST_CODIGO TBL_CURRICULO.CURR_ST_CODIGO%TYPE;',
'W_CURR_ST_DETALHES TBL_CURRICULO.CURR_ST_DETALHES%TYPE;',
'W_CURR_IN_CH_TOTAL TBL_CURRICULO.CURR_IN_CH_TOTAL%TYPE;',
'W_PERIODICIDADE    VARCHAR2(30);',
'BEGIN',
'  OPEN C_CURR;',
'  FETCH C_CURR ',
'  INTO W_CURR_ST_CODIGO, ',
'       W_CURR_ST_DETALHES, ',
'       W_CURR_IN_CH_TOTAL,',
'       W_PERIODICIDADE;',
'  CLOSE C_CURR;',
'  :P43_CURR_ST_CODIGO := W_CURR_ST_CODIGO;',
