wwv_flow_api.create_page_da_action(
 p_id=>wwv_flow_api.id(8338893986787813)
,p_event_id=>wwv_flow_api.id(8338449010787795)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_affected_elements_type=>'ITEM'
,p_affected_elements=>'P49_ENDR_IN_CEP'
,p_attribute_01=>wwv_flow_utilities.join(wwv_flow_t_varchar2(
'$(document).ready(function() {',
'',
'            function limpa_formulário_cep() {',
'                // Limpa valores do formulário de cep.',
'                $("#P49_ENDR_ST_LOGRADOURO").val("");',
'                $("#P49_ENDR_IN_NUMERO").val("");',
'                $("#P49_ENDR_ST_COMPLEMENTO").val("");',
'                $("#P49_ENDR_ST_BAIRRO").val("");',
'                $("#P49_ENDR_ST_UF").val("");',
'                $("#P49_MUNI_IN_CODIGO_CENSO").val("");',
'                $("#P49_MUNI_IN_CODIGO_CENSO_HIDDENVALUE").val("");',
'            }',
'            ',
'            //Quando o campo cep perde o foco.',
'            $("#P49_ENDR_IN_CEP").blur(function() {',
'',
'                //Nova variável "cep" somente com dígitos.',
'                var cep = $(this).val().replace(/\D/g, '''');',
'',
'                //Verifica se campo cep possui valor informado.',
'                if (cep != "") {',
'',
'                    //Expressão regular para validar o CEP.',
'                    var validacep = /^[0-9]{8}$/;',
'',
'                    //Valida o formato do CEP.',
'                    if(validacep.test(cep)) {',
'',
'                        //Preenche os campos com "..." enquanto consulta webservice.',
'                $("#P49_ENDR_ST_LOGRADOURO").val("...");',
'                $("#P49_ENDR_ST_BAIRRO").val("...");',
'                $("#P49_ENDR_ST_MUNICIPIO").val("...");',
'                $("#P49_ENDR_ST_UF").val("...");',
'                $("#P49_MUNI_IN_CODIGO_CENSO").val("...");',
'                $("#P49_MUNI_IN_CODIGO_CENSO_HIDDENVALUE").val("...");',
'',
'                        //Consulta o webservice viacep.com.br/',
'                        $.getJSON("//viacep.com.br/ws/"+ cep +"/json/?callback=?", function(dados) {',
'',
'                            if (!("erro" in dados)) {',
'                                //Atualiza os campos com os valores da consulta.',
'                                $("#P49_ENDR_ST_LOGRADOURO").val(dados.logradouro);',
'                                $("#P49_ENDR_ST_BAIRRO").val(dados.bairro);',
'                                $("#P49_ENDR_ST_MUNICIPIO").val(dados.localidade);',
'                                $("#P49_ENDR_ST_UF").val(dados.uf);',
'                                $("#P49_MUNI_IN_CODIGO_CENSO").val(dados.localidade);',
'$("#P49_MUNI_IN_CODIGO_CENSO_HIDDENVALUE").val(dados.ibge);',
'                            } //end if.',
'                            else {',
'                                //CEP pesquisado não foi encontrado.',
'                                limpa_formulário_cep();',
'                                alert("CEP não encontrado.");',
'                            }',
'                        });',
'                    } //end if.',
'                    else {',
'                        //cep é inválido.',
'                        limpa_formulário_cep();',
'                        alert("Formato de CEP inválido.");',
'                    }',
'                } //end if.',
'                else {',
'                    //cep sem valor, limpa formulário.',
'                    limpa_formulário_cep();',
'                }',
'            });',
'        });'))
,p_stop_execution_on_error=>'Y'
);
