,p_process_name=>'PC_TRATA_TIPO_REFERENCIA'
,p_process_sql_clob=>wwv_flow_utilities.join(wwv_flow_t_varchar2(
'DECLARE',
'  W_INSTR1 NUMBER := instr(:P49_ENDR_ST_REFERENCIA,''_'',1,1);',
'  W_INSTR2 NUMBER := instr(:P49_ENDR_ST_REFERENCIA,''_'',1,2);',
'  W_IN_TIPO_REFERENCIA CHAR(1);',
'  W_DS_TIPO_REFERENCIA VARCHAR2(500);',
'  W_ID_REFERENCIA  VARCHAR2(6);',
'  W_DS_REFERENCIA VARCHAR2(500);',
'BEGIN',
'  ',
'  if (W_INSTR1 > 0 AND W_INSTR2 > 0) then',
'      W_IN_TIPO_REFERENCIA  := SUBSTR(:P49_ENDR_ST_REFERENCIA,1,1);',
'      W_DS_REFERENCIA       := SUBSTR(:P49_ENDR_ST_REFERENCIA,(W_INSTR1+1),(W_INSTR2-1)-W_INSTR1);',
'      W_ID_REFERENCIA       := SUBSTR(:P49_ENDR_ST_REFERENCIA,(W_INSTR2+1));',
'      if (W_IN_TIPO_REFERENCIA=''1'') then',
'          W_DS_TIPO_REFERENCIA := ''Instituição'';',
'      elsif (W_IN_TIPO_REFERENCIA=''2'') then',
'             W_DS_TIPO_REFERENCIA := ''Docente'';',
'      elsif (W_IN_TIPO_REFERENCIA=''3'') then',
'             W_DS_TIPO_REFERENCIA := ''Aluno'';',
'      end if;',
'      ',
'      apex_util.set_session_state(''P49_ENDR_IN_TIPO_REFERENCIA'',W_IN_TIPO_REFERENCIA);',
'      apex_util.set_session_state(''P49_ENDR_ST_TIPO_REFERENCIA'',W_DS_TIPO_REFERENCIA);',
'      apex_util.set_session_state(''P49_ENDR_IN_REFERENCIA'',W_ID_REFERENCIA);',
'      apex_util.set_session_state(''P49_ENDR_ST_REFERENCIA'',W_DS_REFERENCIA);',
'      apex_util.set_session_state(''P49_TIPO_REFERENCIA_DISPLAY'',W_DS_TIPO_REFERENCIA || '' - ''||W_DS_REFERENCIA);',
'      ',
'  end if;',
'  ',
'END;'))
);
