,p_source=>wwv_flow_utilities.join(wwv_flow_t_varchar2(
'select FMED_IN_ID            "FMED_IN_ID", ',
'       FMED_ST_DESCRICAO     "FMED_ST_DESCRICAO", ',
'       FMED_ST_OBSERVACAO    "FMED_ST_OBSERVACAO", ',
'       FMED_ST_CALCULO       "FMED_ST_CALCULO",',
'       CASE TO_CHAR(FMED_IN_FLAG_NIVEL)',
'       WHEN ''1'' THEN ''Modalidade''',
'       WHEN ''2'' THEN ''Curso''',
'       WHEN ''3'' THEN ''Tipo de Disciplina''',
'       END                    "FMED_ST_FLAG_NIVEL",',
'       FC_REFERENCIA_DESCRICAO(''MODALIDADE_ENSINO'',FMED_IN_MODALIDADE) "MODALIDADE_DESCRICAO",',
'       C.CUR_ST_NOME          "CUR_ST_NOME"',
'  from TBL_FORMULA_MEDIA FM',
'     , TBL_CURSO C',
' WHERE C.CUR_IN_ID (+) = FM.CUR_IN_ID',
'   AND (FM.FMED_IN_ID = :P50_FMED_IN_ID AND :P50_FMED_IN_ID IS NOT NULL)',
' order by 4 DESC'))
