wwv_flow_api.create_page_validation(
 p_id=>wwv_flow_api.id(7196159146905320)
,p_validation_name=>'VLD_FORMULA'
,p_validation_sequence=>10
,p_validation=>wwv_flow_utilities.join(wwv_flow_t_varchar2(
'DECLARE',
'  TYPE T_REFCURSOR IS REF CURSOR;',
'  C_REF T_REFCURSOR;',
'  W_SQL TBL_FORMULA_MEDIA.FMED_ST_CALCULO%TYPE;',
'  W_AV1 NUMBER := 10;',
'  W_AV2 NUMBER := 10;',
'  W_AV3 NUMBER := 10;',
'  W_AV4 NUMBER := 10;',
'  W_AV5 NUMBER := 10;',
'  W_AV6 NUMBER := 10;',
'  W_CONTAV NUMBER := 0;',
'  W_RESULT NUMBER := 0;',
'BEGIN',
'  W_SQL := ''SELECT ''||REPLACE(:P50_FMED_ST_CALCULO,''%'',''*(1/100)'')||'' FROM DUAL'';',
'  IF INSTR(:P50_FMED_ST_CALCULO,'':AV1'')>0 THEN',
'    W_CONTAV := W_CONTAV + 1;',
'  END IF;',
'  IF INSTR(:P50_FMED_ST_CALCULO,'':AV2'')>0 THEN',
'    W_CONTAV := W_CONTAV + 1;',
'  END IF;',
'  IF INSTR(:P50_FMED_ST_CALCULO,'':AV3'')>0 THEN',
'    W_CONTAV := W_CONTAV + 1;',
'  END IF;',
'  IF INSTR(:P50_FMED_ST_CALCULO,'':AV4'')>0 THEN',
'    W_CONTAV := W_CONTAV + 1;',
'  END IF;',
'  IF INSTR(:P50_FMED_ST_CALCULO,'':AV5'')>0 THEN',
'    W_CONTAV := W_CONTAV + 1;',
'  END IF;',
'  IF INSTR(:P50_FMED_ST_CALCULO,'':AV6'')>0 THEN',
'    W_CONTAV := W_CONTAV + 1;',
'  END IF;',
'  IF W_CONTAV = 1 THEN',
'     OPEN C_REF FOR W_SQL USING W_AV1;',
'     FETCH C_REF INTO W_RESULT;',
'     CLOSE C_REF;',
'  ELSIF W_CONTAV = 2 THEN',
'     OPEN C_REF FOR W_SQL USING W_AV1, W_AV2;',
'     FETCH C_REF INTO W_RESULT;',
'     CLOSE C_REF;',
'  ELSIF W_CONTAV = 3 THEN',
'     OPEN C_REF FOR W_SQL USING W_AV1, W_AV2, W_AV3;',
'     FETCH C_REF INTO W_RESULT;',
'     CLOSE C_REF;',
'  ELSIF W_CONTAV = 4 THEN',
'     OPEN C_REF FOR W_SQL USING W_AV1, W_AV2, W_AV3, W_AV4;',
'     FETCH C_REF INTO W_RESULT;',
'     CLOSE C_REF;',
'  ELSIF W_CONTAV = 5 THEN',
'     OPEN C_REF FOR W_SQL USING W_AV1, W_AV2, W_AV3, W_AV4, W_AV5;',
'     FETCH C_REF INTO W_RESULT;',
'     CLOSE C_REF;',
'  ELSIF W_CONTAV = 6 THEN',
'     OPEN C_REF FOR W_SQL USING W_AV1, W_AV2, W_AV3, W_AV4, W_AV5, W_AV6;',
'     FETCH C_REF INTO W_RESULT;',
'     CLOSE C_REF;',
'  END IF;',
'  ',
'  APEX_UTIL.set_session_state(p_name => ''P50_DISPLAY_RESULT'', p_value => W_RESULT);',
'',
'EXCEPTION  WHEN OTHERS THEN RAISE_APPLICATION_ERROR(-20002,''Erro ao validar a fórmula'');',
'',
'END;'))
,p_validation_type=>'PLSQL_ERROR'
,p_error_message=>'Erro na VALIDAÇÃO da fórmula'
,p_always_execute=>'N'
,p_validation_condition=>'P50_FMED_ST_CALCULO'
,p_validation_condition_type=>'ITEM_IS_NOT_NULL'
,p_only_for_changed_rows=>'Y'
,p_associated_item=>wwv_flow_api.id(7032581159105352)
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
end;
